fn eval(line: string) -> string {
    let mut st: Vec<int> = Vec::new()
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap()
            let a = st.pop().unwrap()
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(t) {
            st.push(to_int(t))
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    format!("{}", st[0])
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println!("{}", eval(line.trim()))
    }
}
